43:     /**
44:      * @notice deploys Fertilizer and Fertilizer proxy,
45:      * reissues Fertilizer to each holder.
46:      */
47:     function init(
48:         Fertilizers[] calldata fertilizerIds,
49:         uint256 activeFertilizer,
50:         uint256 fertilizedIndex,
51:         uint256 unfertilizedIndex,
52:         uint128 bpf
53:     ) external {
54:         // deploy fertilizer implmentation.
55:         Fertilizer fertilizer = new Fertilizer();
56: 
57:         // deploy fertilizer proxy. Set owner to beanstalk.
58:         TransparentUpgradeableProxy fertilizerProxy = new TransparentUpgradeableProxy(
59:             address(fertilizer),
60:             address(this),
61:             abi.encode(IFertilizer.init.selector)
62:         );
63: 
64:         mintFertilizers(Fertilizer(address(fertilizerProxy)), fertilizerIds);
65:         s.sys.season.fertilizing = true;
66:         s.sys.fert.activeFertilizer = activeFertilizer;
67:         s.sys.fert.fertilizedIndex = fertilizedIndex;
68:         s.sys.fert.unfertilizedIndex = unfertilizedIndex;
69:         s.sys.fert.bpf = bpf;
70:     }
71: 
72:     function mintFertilizers(
73:         Fertilizer fertilizerProxy,
74:         Fertilizers[] calldata fertilizerIds
75:     ) internal {
76:         for (uint i; i < fertilizerIds.length; i++) {
77:             Fertilizers memory f = fertilizerIds[i];
78:             // set s.firstFid, s.nextFid, s.lastFid
79:             uint128 fid = f.fertilizerId;
80:             if (i == 0) s.sys.fert.fertFirst = fid;
81:             if (i != 0) s.sys.fert.nextFid[fertilizerIds[i - 1].fertilizerId] = fid;
82:             if (i == fertilizerIds.length - 1) s.sys.fert.fertLast = fid;
83: 
84:             // reissue fertilizer to each holder.
85:             for (uint j; j < f.accountData.length; j++) {
86:                 // `id` only needs to be set once per account, but is set on each fertilizer
87:                 // as `Fertilizer` does not have a function to set `id` once on a batch.
88:                 fertilizerProxy.beanstalkMint(
89:                     f.accountData[j].account,
90:                     fid,
91:                     f.accountData[j].amount,
92:                     f.accountData[j].lastBpf
93:                 );
94:             }
95:         }
96:     }
97: }
